    77	    pub fn put(&mut self, key: u64, tile: Tile) -> Result<(), (CacheError, Tile)> {
    78	        if !Self::valid_tile(&tile) { return Err((CacheError::InvalidTile, tile)); }
    79	        let charge = tile.allocated_byte_count();
    80	        let available = match self.byte_cap.checked_sub(self.metadata_bytes) {
    81	            Some(n) => n,
    82	            None => return Err((CacheError::MetadataExceedsByteCap, tile)),
    83	        };
    84	        if charge > available { return Err((CacheError::TileExceedsByteCap, tile)); }
    85	
    86	        let mut slot = self.find(key);
    87	        loop {
    88	            let old_charge = slot.and_then(|i| self.slots[i].as_ref()).map_or(0, |e| e.tile.allocated_byte_count());
    89	            let replacing = slot.is_some();
    90	            let projected = self.accounted_bytes().checked_sub(old_charge).and_then(|n| n.checked_add(charge));
    91	            if projected.map_or(false, |n| n <= self.byte_cap) && (replacing || self.count < self.slots.len()) { break; }
    92	            let victim = match self.lru_slot() {
    93	                Some(i) => i,
    94	                None => return Err((CacheError::AccountingOverflow, tile)),
    95	            };
    96	            if Some(victim) == slot { slot = None; }
    97	            self.remove(victim);
    98	        }
    99	        if let Some(i) = slot { self.remove(i); }
   100	        let index = slot.or_else(|| self.slots.iter().position(Option::is_none));
   101	        let Some(index) = index else { return Err((CacheError::AccountingOverflow, tile)); };
   102	        let tick = self.next_tick();
   103	        self.payload_bytes += charge;
   104	        self.count += 1;
   105	        self.slots[index] = Some(Entry { key, tile, used_epoch: self.clock_epoch, used_tick: tick });
   106	        Ok(())
   107	    }
